@CrossOrigin
@RestController
@RequestMapping("/PatientQuery")
public class PatientQueryRestController extends BaseSpringRestController {
	
	public PatientQueryRestController( PatientService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Patient using a UUID
     * @param		UUID patientId
     * @return		Patient
     */    
    @GetMapping("/load")
    public Patient load( @RequestParam(required=true) UUID patientId ) {
    	Patient entity = null;

    	try {  
    		entity = service.getPatient( new PatientFetchOneSummary( patientId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Patient using Id " + patientId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Patient business objects
     * @return		Set<Patient>
     */
    @GetMapping("/")
    public List<Patient> loadAll() {                
    	List<Patient> patientList = null;
        
    	try {
            // load the Patient
            patientList = service.getAllPatient();
            
            if ( patientList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Patients" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Patients ", exc );
        	return null;
        }

        return patientList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Patient patient = null;
    protected PatientService service = null;
    private static final Logger LOGGER = Logger.getLogger(PatientQueryRestController.class.getName());
    
}
